#include "stdlib/stats/base/ndarray/dcovarmtk.h"
#include "stdlib/stats/strided/dcovarmtk.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/blas/base/shared.h"

/**
* Computes the covariance of two one-dimensional double-precision floating-point ndarrays provided known means and using a one-pass textbook algorithm.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   first one-dimensional input ndarray.
*     -   second one-dimensional input ndarray.
*     -   a zero-dimensional ndarray specifying the degrees of freedom adjustment.
*     -   a zero-dimensional ndarray specifying the mean of the first one-dimensional ndarray.
*     -   a zero-dimensional ndarray specifying the mean of the second one-dimensional ndarray.
*
* @param arrays    list containing ndarrays
* @return          covariance
*/
double stdlib_stats_dcovarmtk( const struct ndarray *arrays[] ) {
	const struct ndarray *x = arrays[ 0 ];
	const struct ndarray *y = arrays[ 1 ];

	double correction;
	double meanx;
	double meany;
	stdlib_ndarray_get_float64( arrays[ 2 ], NULL, &correction );
	stdlib_ndarray_get_float64( arrays[ 3 ], NULL, &meanx );
	stdlib_ndarray_get_float64( arrays[ 4 ], NULL, &meany );

	return API_SUFFIX(stdlib_strided_dcovarmtk_ndarray)( stdlib_ndarray_dimension( x, 0 ), correction, meanx, (const double *)stdlib_ndarray_data( x ), stdlib_ndarray_stride_elements( x, 0 ), stdlib_ndarray_offset_elements( x ), meany, (const double *)stdlib_ndarray_data( y ), stdlib_ndarray_stride_elements( y, 0 ), stdlib_ndarray_offset_elements( y ) );
}
